head.script:
scwin.gVar = {
    "cLabel" : "",
    "cLocaleRef" : "",
    "cUseLocale" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > unbindRef]<br/>Textarea 컴포넌트의 데이터 바인딩을 해제합니다.",
    "validation" : [
        "Textarea 컴포넌트의 데이터 바인딩을 해제할 수 있어야 합니다.",
        "바인딩된 상태에서만 동작하며, ref 속성값이 빈 문자열로 초기화되어야 합니다.",
        "메소드로 ref 속성값을 제거해도 컴포넌트에 입력된 값은 유지되어야 합니다.",
        "ref 속성이 설정되지 않은 상태에서 메소드가 실행되면 무동작이며 입력된 값이 유지되어야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 공통 wframe 의 btn_getText_onclick 은 textarea 의 render.textContent 를 읽어 입력값을 못 가져옴
    // → textarea 의 getValue() API 를 사용하도록 override
    wf_sample.getObj("scwin").btn_getText_onclick = function () {
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("text : " + target1.getValue());
    };

    // 공통 wframe 의 btn_ref_onclick 은 textarea 의 render.textContent 를 읽으므로 getValue() 로 override
    wf_sample.getObj("scwin").btn_ref_onclick = function () {
        let rtn = '';

        // ref 확인
        rtn = target1.options.ref;
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("ref : " + rtn);

        // text 확인 (textarea 는 getValue 사용)
        rtn = target1.getValue();
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("text : " + rtn);
    };
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        // label: scwin.gVar["cLabel"],
        // localeRef: scwin.gVar["cLocaleRef"],
        // useLocale: scwin.gVar["cUseLocale"],
    };

    let cList = $c.gcm.createCList(properties);

    // empty textarea 동적 생성 (ref 바인딩 테스트에는 비어있는 textarea 사용)
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:textarea ' + $c.gcm.strNameSpace + ' ' + cList + ' id="" style="width:300px; height:100px;"></xf:textarea>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        'textarea',
        strTarget,
        grp_comp
    );

    // textarea 는 label / localeRef / useLocale 속성이 없으므로 condition 영역을 비활성화한다.
    wf_sample.getObj("con_label") && wf_sample.getObj("con_label").setDisabled(true);
    wf_sample.getObj("con_localeRef") && wf_sample.getObj("con_localeRef").setDisabled(true);
    wf_sample.getObj("con_useLocale") && wf_sample.getObj("con_useLocale").setDisabled(true);
}
